1	// The one shared object every module reads: the save (G.S) and what is happening on screen right now.
2	import { defaultPlan, defaultSchool, addSeasonNumbers, numberPlan, migrateNumber, DEFAULT_HAIR } from './plan.js';
3	import { NUMBERS } from './data.js';
4	
5	export const G = {
6	  S: null, lang: 'fr',
7	  screen: 'prep', tab: 'order', run: null, speed: 1, follow: true,
8	  pickedRoom: null, armed: null, selected: null,
9	  pickNum: 'G1', editB: false, pickDancer: null, ruler: null,
10	  realT: 0, frames: 0,
11	};
12	
13	/* ---------------- the save ---------------- */
14	const SAVE_KEY = 'gala-game-v2', OLD_KEY = 'gala-toy-v1';
15	export function fresh() {
16	  return { v: 2, lang: 'fr', season: 1, galaDone: false, seenIntro: 0, plan: defaultPlan(), school: defaultSchool(), notebook: [], sound: true, seed: (Math.random() * 1e9) >>> 0 };
17	}
18	// round 1's save: the running order, the formation and the goûter carry over; costumes per class become costumes per number
19	function fromRound1(o) {
20	  const s = fresh(), p = s.plan;
21	  try {
22	    if (o.plan) {
23	      p.start = o.plan.start ?? p.start; p.interval = o.plan.interval ?? p.interval;
24	      if (Array.isArray(o.plan.order) && o.plan.order.every((id) => NUMBERS[id] || ['accueil', 'entracte', 'final'].includes(id))) p.order = o.plan.order;
25	      if (Array.isArray(o.plan.formation) && o.plan.formation.length === 8) p.numbers.G1.A = o.plan.formation.map((q) => ({ x: q.x, z: q.z }));
26	      p.cakeG = o.plan.cakeG ?? p.cakeG; p.bottles = o.plan.bottles ?? p.bottles;
27	    }
28	    if (o.school) {
29	      s.school.name = o.school.name || '';
30	      const cos = o.school.costumes || {};
31	      for (const [id, np] of Object.entries(p.numbers)) { const c = cos[NUMBERS[id].cls]; if (c) { np.costume.color = c.color; if (['tutu', 'jupette', 'justaucorps'].includes(c.style)) np.costume.outfit = c.style; } }
32	      for (const [cls, c] of Object.entries(cos)) { const h = { bun: 'chignon', ponytail: 'queue', braids: 'tresses', bob: 'carre' }[c.hair]; if (h) p.hair[cls] = h; }
33	    }
34	    s.lang = o.lang || 'fr';
35	  } catch { /* a broken old save starts fresh */ }
36	  return s;
37	}
38	// fill in anything a newer version added, so an older save keeps working
39	function mend(s) {
40	  const f = fresh();
41	  for (const k of Object.keys(f)) if (s[k] === undefined) s[k] = f[k];
42	  for (const k of Object.keys(f.plan)) if (s.plan[k] === undefined) s.plan[k] = f.plan[k];
43	  for (const k of Object.keys(f.school)) if (s.school[k] === undefined) s.school[k] = f.school[k];
44	  addSeasonNumbers(s.plan, s.season);
45	  for (const id of Object.keys(s.plan.numbers)) { const np = s.plan.numbers[id]; s.plan.numbers[id] = np.blocks || np.moves ? migrateNumber(np) : numberPlan(id); }
46	  for (const c of Object.keys(DEFAULT_HAIR)) if (!s.plan.hair[c] && c in s.plan.hair) s.plan.hair[c] = DEFAULT_HAIR[c];
47	  return s;
48	}
49	export function load() {
50	  try {
51	    const raw = localStorage.getItem(SAVE_KEY);
52	    if (raw) { const s = JSON.parse(raw); if (s && s.v === 2) { G.S = mend(s); G.lang = G.S.lang || 'fr'; return; } }
53	    const old = localStorage.getItem(OLD_KEY);
54	    if (old) { const o = JSON.parse(old); if (o && o.v === 1) { G.S = mend(fromRound1(o)); G.lang = G.S.lang; return; } }
55	  } catch { /* storage blocked: play without a save */ }
56	  G.S = fresh(); G.lang = 'fr';
57	}
58	export function save() { try { G.S.lang = G.lang; localStorage.setItem(SAVE_KEY, JSON.stringify(G.S)); } catch { /* storage blocked */ } }
59	export function resetAll() { G.S = fresh(); save(); }
60

