1	// The engine's tests: the opening plan is wrong in the ways round 1 taught, and every season can be solved by hand.
2	import test from 'node:test';
3	import assert from 'node:assert/strict';
4	import { simulate, judgeSpacing, judgeMusic, routineInfo, danceOf, analyseLoge, againstWall, changeTime } from '../src/engine.js';
5	import { defaultPlan, defaultSchool, addSeasonNumbers, oneBlock, migrateNumber } from '../src/plan.js';
6	import { CLS, NUMBERS, MOVES, hm } from '../src/data.js';
7	
8	const solveY1 = (plan) => {
9	  plan.interval = 1200;
10	  plan.numbers.G1.A = [[-4.5, 1.5], [-2.5, 1.5], [-0.5, 1.5], [1.5, 1.5], [3.5, 1.5], [-3.5, 3.5], [-1.5, 3.5], [0.5, 3.5]].map(([x, z]) => ({ x, z }));
11	  Object.assign(plan.numbers.G1, oneBlock(['plie', 'bras', 'arabesque', 'descente', 'remonte', 'reverence'], 15));
12	  plan.cakeG = 1850; plan.bottles = 4; plan.snack = 'fruits';
13	  return plan;
14	};
15	
16	test('the opening plan: late, the little ones up past bedtime, hands touching, the music, no cake for the seniors', () => {
17	  const r = simulate({ plan: defaultPlan(), school: defaultSchool(), season: 1 });
18	  assert.ok(r.order.late > 0); assert.ok(r.order.sleepy > 0);
19	  assert.ok(r.perf.G1.spacing.collide.length > 0); assert.equal(r.perf.G1.music.diff, 32);
20	  assert.ok(r.perf.G1.info.links.some((l) => l.gap === 2));
21	  assert.equal(r.gouter.cakeOut, 'grandes'); assert.equal(r.ok, false);
22	});
23	test('season 1 solved: a perfect evening earns the bonus', () => {
24	  const r = simulate({ plan: solveY1(defaultPlan()), school: defaultSchool(), season: 1 });
25	  assert.equal(r.order.ok, true, JSON.stringify({ late: r.order.late, sleepy: r.order.sleepy }));
26	  for (const p of Object.values(r.perf)) { assert.ok(p.spacing.ok, p.id); assert.ok(p.music.ok, p.id); }
27	  assert.ok(r.gouter.ok); assert.ok(r.allOk); assert.ok(r.pts.some(([k]) => k === 'perfect'));
28	});
29	test('a rehearsal never slips; a gala rolls the dice and is the same for the same seed', () => {
30	  const plan = solveY1(defaultPlan()), school = defaultSchool();
31	  const reh = simulate({ plan, school, season: 1 }); assert.ok(Object.values(reh.perf).every((p) => p.slips.length === 0));
32	  const a = simulate({ plan, school, season: 1, mode: 'gala', seed: 5 }), b = simulate({ plan, school, season: 1, mode: 'gala', seed: 5 });
33	  assert.deepEqual(Object.values(a.perf).map((p) => p.slips.length), Object.values(b.perf).map((p) => p.slips.length));
34	});
35	test('too few hair stations delay the curtain; a make-up table fixes it', () => {
36	  const school = defaultSchool(); school.furniture = school.furniture.filter((f) => f.id !== 'miroir');
37	  const r = simulate({ plan: solveY1(defaultPlan()), school, season: 1 });
38	  assert.ok(r.order.startLate > 0);
39	  school.furniture.push({ id: 'coiffeuse', c: 7, r: 0, rot: 0 });
40	  assert.equal(simulate({ plan: solveY1(defaultPlan()), school, season: 1 }).order.startLate, 0);
41	});
42	test('a mirror facing the wall does nothing; turned round it counts', () => {
43	  const school = defaultSchool(); school.furniture = [{ id: 'miroir', c: 3, r: 0, rot: 2 }];
44	  assert.equal(analyseLoge(school, 24).postesRaw, 0);
45	  school.furniture[0].rot = 0; assert.equal(analyseLoge(school, 24).postesRaw, 1);
46	  assert.equal(againstWall({ id: 'miroir', c: 9, r: 3, rot: 1 }, 10), true);
47	});
48	test('furniture changes costume changes: a screen and a shoe shelf make it quicker, a crowded room slower', () => {
49	  const prev = { outfit: 'tutu', shoes: 'demi', acc: 'aucun' }, next = { outfit: 'fee', shoes: 'pointes', acc: 'ailes' };
50	  const bare = changeTime(prev, next, { shoes: 0, railCap: 8, totalDancers: 24, screen: 0, clutter: false });
51	  const good = changeTime(prev, next, { shoes: 1, railCap: 24, totalDancers: 24, screen: 1, clutter: false });
52	  assert.ok(good.min < bare.min);
53	});
54	test('a phrase that travels drifts off the stage over its repeats', () => {
55	  const np = { ...defaultPlan().numbers.G2, moves: ['chasseD', 'plie', 'bras', 'plie', 'bras', 'plie'], repeats: 15 };
56	  const sp = judgeSpacing(np, CLS.grandes, { halfW: 5.5, depth: 5 }, routineInfo(np.moves, 'classique'));
57	  assert.ok(sp.offstage.length > 0);
58	});
59	test('changing places: two dancers crossing on the same line bump', () => {
60	  const np = { ...defaultPlan().numbers.G2, moves: ['echange', 'plie', 'bras', 'bras', 'plie'], repeats: 15 };
61	  np.B = np.A.map((p) => ({ ...p })); [np.B[0], np.B[1]] = [{ ...np.A[1] }, { ...np.A[0] }];
62	  const sp = judgeSpacing(np, CLS.grandes, { halfW: 5.5, depth: 5 }, routineInfo(np.moves, 'classique'));
63	  assert.ok(sp.bump.some((b) => (b.i === 0 && b.j === 1)));
64	});
65	test('season 2: parents late with 30 min; doors at 45 min seats everyone', () => {
66	  const plan = addSeasonNumbers(solveY1(defaultPlan()), 2), school = defaultSchool();
67	  assert.ok(simulate({ plan, school, season: 2 }).parking.lateCars > 0);
68	  plan.parking.doors = 45; assert.equal(simulate({ plan, school, season: 2 }).parking.lateCars, 0);
69	});
70	test('season 3: the teens join, the evening needs reordering and can still be perfect', () => {
71	  const plan = addSeasonNumbers(solveY1(defaultPlan()), 3), school = defaultSchool();
72	  assert.ok(plan.order.includes('A1') && plan.order.includes('A2'));
73	  assert.equal(simulate({ plan, school, season: 3 }).order.ok, false);
74	  plan.start = hm(19, 45); plan.interval = 600;
75	  plan.order = ['accueil', 'P1', 'A1', 'M1', 'P2', 'G1', 'entracte', 'M2', 'A2', 'G2', 'final'];
76	  school.furniture.push({ id: 'coiffeuse', c: 7, r: 0, rot: 0 });
77	  plan.cakeG = 2600; plan.bottles = 5; plan.parking.doors = 45;
78	  const r = simulate({ plan, school, season: 3 });
79	  assert.equal(r.order.ok, true, JSON.stringify({ late: r.order.late, sleepy: r.order.sleepy, yawns: r.order.yawns, waits: r.order.waits.map((w) => [w.id, w.wait]), startLate: r.order.startLate }));
80	});
81	
82	/* ---------------- round 2½: blocks and a chain, try-outs that roll the dice, twisted ankles ---------------- */
83	test('a dance is blocks in a chain: read flat, and the music judged on the sum of the chain', () => {
84	  const np = { ...defaultPlan().numbers.G1, blocks: [{ id: 'a', name: 'Intro', moves: ['plie', 'bras', 'tourne', 'bras'] }, { id: 'b', name: 'Sauts', moves: ['plie', 'plie', 'plie', 'plie'] }], chain: [] };
85	  const len = (id) => np.blocks.find((b) => b.id === id).moves.reduce((s, m) => s + MOVES[m].c, 0);
86	  assert.equal(len('a'), 24); assert.equal(len('b'), 16);
87	  np.chain = [...Array(10).fill('a'), ...Array(15).fill('b')];
88	  const d = danceOf(np), info = routineInfo(d.moves, 'classique', false), m = judgeMusic('G1', d, info);
89	  assert.equal(d.moves.length, 10 * 4 + 15 * 4); assert.equal(d.chainLen, 25); assert.equal(d.mostRepeated, 15); assert.equal(d.blocksUsed, 2);
90	  assert.equal(m.have, 480); assert.ok(m.ok); assert.deepEqual(m.parts, [...Array(10).fill(24), ...Array(15).fill(16)]);
91	  np.chain.push('a'); const over = judgeMusic('G1', danceOf(np), routineInfo(danceOf(np).moves, 'classique', false));
92	  assert.equal(over.diff, 24); assert.equal(over.stopsIn, 26, 'the music stops in the 26th block of the chain');
93	});
94	test('an older save (one phrase × repeats) becomes one block chained as often: the same dance, the same verdicts', () => {
95	  const plan = solveY1(defaultPlan()), old = JSON.parse(JSON.stringify(plan));
96	  for (const np of Object.values(old.numbers)) { const b = np.blocks[0]; np.moves = b.moves; np.repeats = np.chain.length; delete np.blocks; delete np.chain; }
97	  for (const id of Object.keys(old.numbers)) old.numbers[id] = migrateNumber(old.numbers[id]);
98	  const a = simulate({ plan, school: defaultSchool(), season: 1 }), b = simulate({ plan: old, school: defaultSchool(), season: 1 });
99	  assert.deepEqual(Object.values(b.perf).map((p) => [p.id, p.total, p.music.have]), Object.values(a.perf).map((p) => [p.id, p.total, p.music.have]));
100	});
101	test('a try-out rolls the dice (each seed its own), the general rehearsal does not; a hard step for the little ones goes wrong', () => {
102	  const plan = solveY1(defaultPlan()), school = defaultSchool();
103	  Object.assign(plan.numbers.P1, oneBlock(['fouette', 'grandJete', 'reception', 'plie', 'plie', 'plie', 'plie'], 9));
104	  const slipsOf = (mode, seed) => simulate({ plan, school, season: 1, mode, seed }).perf.P1.slips;
105	  assert.equal(slipsOf('rehearsal', 1).length, 0);
106	  const tries = Array.from({ length: 6 }, (_, k) => slipsOf('try', 100 + k));
107	  assert.ok(tries.every((s) => s.length > 0), JSON.stringify(tries.map((s) => s.length)));
108	  assert.notDeepEqual(tries[0], tries[1]);
109	  const all = tries.flat(), d = danceOf(plan.numbers.P1);
110	  assert.ok(all.some((s) => s.kind === 'ankle'), 'someone twists an ankle somewhere in six tries');
111	  for (const s of all.filter((x) => x.kind === 'ankle')) assert.ok(MOVES[d.moves[s.k]].d > CLS.petits.exp, 'an ankle only on a step above their level');
112	  for (const s of tries[0]) if (s.kind === 'ankle') assert.ok(!tries[0].some((x) => x.i === s.i && x.k > s.k), 'after the ankle she dances no more');
113	});
114

